INSERT INTO "public"."farming_calendar" VALUES (1, NULL, '春梢萌发期', '惊蛰', 2, 19, 3, 5, '加强水肥管理，促进春梢生长。注意防治疮痂病、红蜘蛛、蚜虫。', '["S12", "S14"]', 1, 't', '2026-07-11 06:24:30.589342', '2026-07-11 06:24:30.589342');
INSERT INTO "public"."farming_calendar" VALUES (2, NULL, '花蕾-开花期', '清明', 3, 20, 4, 20, '保花保果，注意防治蓟马、花蕾蛆。避免使用高毒农药。', '["S12", "S14"]', 2, 't', '2026-07-11 06:24:30.589342', '2026-07-11 06:24:30.589342');
INSERT INTO "public"."farming_calendar" VALUES (3, NULL, '谢花-幼果期', '谷雨', 4, 20, 5, 20, '保果稳果，重点防治溃疡病、炭疽病。加强水肥管理。', '["S14", "S10"]', 3, 't', '2026-07-11 06:24:30.589342', '2026-07-11 06:24:30.589342');
INSERT INTO "public"."farming_calendar" VALUES (4, NULL, '夏梢期', '芒种', 5, 21, 7, 7, '控制夏梢生长，防治潜叶蛾、柑橘木虱。注意排水防涝。', '["S1", "S2"]', 4, 't', '2026-07-11 06:24:30.589342', '2026-07-11 06:24:30.589342');
INSERT INTO "public"."farming_calendar" VALUES (5, NULL, '果实膨大期', '大暑', 7, 7, 9, 7, '加强水肥管理，注意抗旱。重点防治锈壁虱、红蜘蛛。注意防日灼。', '["S1", "S2"]', 5, 't', '2026-07-11 06:24:30.589342', '2026-07-11 06:24:30.589342');
INSERT INTO "public"."farming_calendar" VALUES (6, NULL, '秋梢期', '白露', 9, 7, 10, 8, '放好秋梢，防治潜叶蛾、木虱。注意防治炭疽病。', '["S1", "S2"]', 6, 't', '2026-07-11 06:24:30.589342', '2026-07-11 06:24:30.589342');
INSERT INTO "public"."farming_calendar" VALUES (7, NULL, '果实成熟期', '霜降', 10, 8, 12, 7, '适时采收，注意防治炭疽病（蒂腐）。做好冬季清园准备。', '["S10", "S13"]', 7, 't', '2026-07-11 06:24:30.589342', '2026-07-11 06:24:30.589342');
